create table if not exists public.schoolpro_transcript_settings(school_id uuid primary key references public.schoolpro_schools(id),officers jsonb not null default '[{"role":"Examination officer","name":"","comment":"","signature_path":""},{"role":"Principal","name":"","comment":"","signature_path":""},{"role":"Director","name":"","comment":"","signature_path":""}]',updated_at timestamptz not null default now());
alter table public.schoolpro_transcript_settings enable row level security;
create policy transcript_settings_read on public.schoolpro_transcript_settings for select to authenticated using(public.schoolpro_member_can_manage(school_id) or private.schoolpro_can_issue_transcript(school_id));
create policy transcript_settings_write on public.schoolpro_transcript_settings for all to authenticated using(public.schoolpro_member_can_manage(school_id) or private.schoolpro_can_issue_transcript(school_id)) with check(public.schoolpro_member_can_manage(school_id) or private.schoolpro_can_issue_transcript(school_id));
grant select,insert,update on public.schoolpro_transcript_settings to authenticated;
create or replace function private.schoolpro_transcript_enrichment() returns trigger language plpgsql security definer set search_path='' as $$
begin
new.snapshot:=new.snapshot||jsonb_build_object('format_version',2,'officers',coalesce((select officers from public.schoolpro_transcript_settings where school_id=new.school_id),'[]'::jsonb),'logo_url',(select logo_url from public.schoolpro_branding where school_id=new.school_id limit 1),
'period_details',coalesce((select jsonb_agg(jsonb_build_object('session',p.session,'term',p.term,'attendance',(select jsonb_build_object('recorded',count(*),'present',count(*)filter(where a.status::text in('present','late')),'absent',count(*)filter(where a.status::text='absent'),'excused',count(*)filter(where a.status::text='excused')) from public.schoolpro_attendance a where a.school_id=new.school_id and a.student_id=new.student_id and a.session=p.session and a.term=p.term),
'ratings',coalesce((select jsonb_agg(jsonb_build_object('name',d.name,'domain',d.domain_type,'rating',coalesce(nullif(r.rating_label,''),r.rating::text))order by d.position)from public.schoolpro_result_domain_ratings r join public.schoolpro_result_domain_definitions d on d.id=r.definition_id and d.school_id=r.school_id where r.school_id=new.school_id and r.student_id=new.student_id and r.session=p.session and r.term=p.term),'[]'::jsonb),
'teacher_comments',coalesce((select jsonb_agg(distinct teacher_comment) filter(where nullif(teacher_comment,'')is not null)from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.session=p.session and r.term=p.term and r.status='published'),'[]'::jsonb),
'principal_comments',coalesce((select jsonb_agg(distinct head_teacher_comment) filter(where nullif(head_teacher_comment,'')is not null)from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.session=p.session and r.term=p.term and r.status='published'),'[]'::jsonb))
 order by p.session,p.term) from(select distinct r.session,r.term from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.status='published')p),'[]'::jsonb));
return new;
end $$;
revoke all on function private.schoolpro_transcript_enrichment() from public,anon,authenticated;
create trigger schoolpro_transcript_enrichment before insert on public.schoolpro_transcript_issues for each row execute function private.schoolpro_transcript_enrichment();